mapper.update:
update dish
name = #{name}, category_id = #{categoryId}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser}
where id = #{id}

mapper.select:
select d.*, c.name as categoryName from dish d left join category c on d.category_id = c.id
and d.name like concat('%', #{name}, '%')
and d.category_id = #{categoryId}
and d.status = #{status}
order by d.update_time desc

select * from dish


        and name like concat('%', #{name}, '%')


        and category_id = #{categoryId}


        and status = #{status}


order by update_time desc

select d.id as dishId, d.name, d.price from dish d
d.status = 1
and ( d.name like concat('%', #{keyword}, '%') or d.description like concat('%', #{keyword}, '%') )
and d.category_id = #{categoryId}
and d.price >= #{minPrice}
and d.price <= #{maxPrice}
and exists ( select 1 from dish_flavor df_spicy where df_spicy.dish_id = d.id and df_spicy.name = '辣度' and json_contains( df_spicy.value, json_quote(#{spicyLevel}) ) )
and exists ( select 1 from dish_flavor df_dislike where df_dislike.dish_id = d.id and df_dislike.name = '忌口' and json_contains( df_dislike.value, json_quote( concat('不要', #{ingredient}) ) ) )
order by d.id desc limit #{limit}
